  if (a === 'robe') return ({ idle: ["..8cccccccccc8..", "....22....22...."], walk: ["..8cccccccccc8..", "...22......22..."], walk2: ["...8cccccccccc8.", ".....22..22....."] }[f] || ["..8cccccccccc8..", "....22....22...."]).map(s => s.replace(/c/g, b));
